        instancedMesh.getMatrixAt(inst, instanceMatrix);

        // Combine instance matrix with world matrix
        const fullMatrix = new THREE.Matrix4();
        fullMatrix.multiplyMatrices(instancedMesh.matrixWorld, instanceMatrix);
        const normalMatrix = new THREE.Matrix3().getNormalMatrix(fullMatrix);

        const startVertex = indexVertex + nbVertex;
        const startNormals = indexNormals + nbNormals;

        // Output vertices for this instance
        if (vertices) {
          for (let i = 0; i < vertices.count; i++) {
            vertex.fromBufferAttribute(vertices, i);
            vertex.applyMatrix4(fullMatrix);
            output += 'v ' + vertex.x + ' ' + vertex.y + ' ' + vertex.z + '\n';
            nbVertex++;
          }
        }

        // Output normals for this instance
        if (normals) {
          for (let i = 0; i < normals.count; i++) {
            normal.fromBufferAttribute(normals, i);
            normalWorld.copy(normal).applyMatrix3(normalMatrix).normalize();
            output += 'vn ' + normalWorld.x + ' ' + normalWorld.y + ' ' + normalWorld.z + '\n';
            nbNormals++;
          }
        }

        // Output faces for this instance
        if (indices) {
          for (let i = 0; i < indices.count; i += 3) {
            const a = indices.getX(i) + 1 + startVertex;
            const b = indices.getX(i + 1) + 1 + startVertex;
            const c = indices.getX(i + 2) + 1 + startVertex;

            if (normals) {
              const na = indices.getX(i) + 1 + startNormals;
              const nb = indices.getX(i + 1) + 1 + startNormals;
              const nc = indices.getX(i + 2) + 1 + startNormals;
              output += 'f ' + a + '//' + na + ' ' + b + '//' + nb + ' ' + c + '//' + nc + '\n';
            } else {
              output += 'f ' + a + ' ' + b + ' ' + c + '\n';
            }
          }
        } else if (vertices) {
          for (let i = 0; i < vertices.count; i += 3) {
            const a = i + 1 + startVertex;
            const b = i + 2 + startVertex;
            const c = i + 3 + startVertex;

            if (normals) {
              const na = i + 1 + startNormals;
              const nb = i + 2 + startNormals;
              const nc = i + 3 + startNormals;
              output += 'f ' + a + '//' + na + ' ' + b + '//' + nb + ' ' + c + '//' + nc + '\n';
            } else {
              output += 'f ' + a + ' ' + b + ' ' + c + '\n';
            }
          }
        }
      }

      return { nbVertex, nbNormals };
    };

    // Traverse the object hierarchy
    object.traverse((child) => {
      if (child.isMesh) {
        output += 'o ' + (child.name || 'mesh') + '\n';

        let result;
        if (child.isInstancedMesh) {
          result = parseInstancedMesh(child);
        } else {
          result = parseMesh(child);
        }

        indexVertex += result.nbVertex;
        indexNormals += result.nbNormals;
      }
    });

    return output;
  }
}

// Create the scene
const scene = createScene();

// Apply -90 degrees X-rotation to convert from Three.js Y-up to Blender Z-up
// Rotation of -90 degrees = -PI/2 radians around X-axis
const rotationMatrix = new THREE.Matrix4();
rotationMatrix.makeRotationX(-Math.PI / 2);

// Apply the rotation to the root object
scene.applyMatrix4(rotationMatrix);

// Update world matrices for all objects
scene.updateMatrixWorld(true);

// Export to OBJ
const exporter = new OBJExporter();
const objContent = exporter.parse(scene);

// Write to file
fs.writeFileSync('/root/output/object.obj', objContent);

console.log('Successfully exported to /root/output/object.obj');
